{
  "findings": [
    {
      "check_id": "CKV_AZURE_10",
      "title": "Role definition with wildcard permissions in not_actions",
      "resource": "azurerm_role_definition.example2",
      "severity": "HIGH",
      "explanation": "The role definition uses `not_actions = ["*"]` which effectively grants all actions on the subscription scope, creating a highly privileged custom role that violates the principle of least privilege."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Conflicting role assignment arguments",
      "resource": "azurerm_role_assignment.example2",
      "severity": "MEDIUM",
      "explanation": "The resource specifies both `role_definition_name` and `role_definition_id`. In Terraform's AzureRM provider, these are mutually exclusive; providing both can lead to unpredictable behavior or errors during apply. The intent appears to be assigning the custom role defined above, so the name should be removed."
    }
  ],
  "patched_code": "resource "azurerm_role_definition" "example2" {
  name        = "my-custom-role"
  scope       = data.azurerm_subscription.primary.id
  description = "This is a custom role created via Terraform"

  permissions {
    actions     = []
    not_actions = []
  }

  assignable_scopes = [
    data.azurerm_subscription.primary.id,
  ]
}

resource "azurerm_role_assignment" "example2" {
  name               = "00000000-0000-0000-0000-000000000000"
  scope              = data.azurerm_subscription.primary.id
  role_definition_id = azurerm_role_definition.example2.role_definition_resource_id
  principal_id       = data.azurerm_client_config.example.object_id
}",
  "fix_summary": "Removed the wildcard `*` from `not_actions` in the role definition to prevent granting excessive privileges (least privilege violation). Removed the conflicting `role_definition_name` argument from the role assignment to ensure it correctly references only the custom role ID."
}
